#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_safeRender;
uniform float amzp_style;
uniform float amzp_amount;
uniform float amzp_paintProg;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_before;
uniform float amzp_brushSize;
uniform float amzp_strokeLen;
uniform float amzp_strokeWid;
uniform float amzp_jitter;
uniform float amzp_edgeFollow;
uniform float amzp_swirl;
uniform float amzp_swirlScale;
uniform float amzp_swirlMove;
uniform float amzp_baseAngle;
uniform float amzp_flowSmooth;
uniform float amzp_bristle;
uniform float amzp_impasto;
uniform float amzp_lightAngle;
uniform float amzp_outline;
layout(color) uniform half4 amzp_outlineColor;
uniform float amzp_saturation;
uniform float amzp_contrast;
uniform float amzp_colorVar;
uniform float amzp_levels;
uniform float amzp_canvasAmt;
uniform float amzp_canvasScale;
layout(color) uniform half4 amzp_canvasColor;
uniform float amzp_boil;
uniform float amzp_boilFps;
uniform float amzp_layers;
uniform float amzp_seed;
uniform float amzp_advScale;
uniform float amzp_overdrawOn;
    float2 advRot(float2 q, float a) { float cs = cos(a), sn = sin(a); return float2(cs * q.x - sn * q.y, sn * q.x + cs * q.y); }
    float prog(float p) { return (amzp_autop>0.5) ? p + time * (amzp_autoSpeed * 0.25) : p; }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    bool inside(float2 uv) { return uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0; }
    float4 layerAt(float2 uv) { return inside(uv) ? amzTexture(0, l2s(uv)) : float4(0.0); }
    float pxs() { return screen.zw.x / max(screen.zw.x, 1.0); }
    float3 hue(float h) { return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0); }
    float hh(float x) { return fract(sin(x * 91.345 + amzp_seed * 13.7) * 43758.5453); }
    float vn1(float x) { float i = floor(x), f = fract(x); f = f * f * (3.0 - 2.0 * f); return mix(hh(i), hh(i + 1.0), f); }
    float gpx; float2 gW; float gfr;
    float hs(float2 p, float k) { return fract(sin(dot(p, float2(127.1, 311.7)) + k * 74.7 + amzp_seed * 3.91 + gfr * 17.13) * 43758.5453); }
    float vn(float2 p, float k) {
        float2 i = floor(p), f = fract(p);
        f = f * f * (3.0 - 2.0 * f);
        return mix(mix(hs(i, k), hs(i + float2(1.0, 0.0), k), f.x), mix(hs(i + float2(0.0, 1.0), k), hs(i + float2(1.0, 1.0), k), f.x), f.y);
    }
    float4 src(float2 pp) {
        float2 uv0 = pp * gpx / gW;
        if ((amzp_overdrawOn>0.5) && !inside(uv0)) return float4(0.0);
        float2 uv = clamp(uv0, 0.0, 1.0);
        float4 c = amzTexture(0, l2s(uv));
        return c.a > 0.0001 ? float4(c.rgb / c.a, c.a) : float4(0.0);
    }
    float luma(float3 c) { return dot(c, float3(0.299, 0.587, 0.114)); }
    float3 blurAt(float2 p, float r) {
        float3 a = src(p).rgb * 2.0;
        a += src(p + float2(r, 0.0)).rgb + src(p - float2(r, 0.0)).rgb + src(p + float2(0.0, r)).rgb + src(p - float2(0.0, r)).rgb;
        a += src(p + float2(r, r) * 0.7).rgb + src(p - float2(r, r) * 0.7).rgb + src(p + float2(r, -r) * 0.7).rgb + src(p - float2(r, -r) * 0.7).rgb;
        return a / 10.0;
    }
    float2 swirlVec(float2 c) {
        float Sw = max(amzp_swirlScale, 0.05) * 420.0;
        float2 g = c / Sw + float2(3.1, 1.7);
        float2 gi = floor(g - 0.5);
        float2 acc = float2(0.0);
        for (int j = 0; j < 2; j++) {
            for (int i = 0; i < 2; i++) {
                float2 id = gi + float2(float(i), float(j));
                float2 cc = (id + 0.5 + (float2(hs(id, 1.0), hs(id, 2.0)) - 0.5) * 0.8) * Sw - float2(3.1, 1.7) * Sw;
                float2 r = c - cc;
                float rl = length(r);
                float sg = hs(id, 3.0) < 0.5 ? 1.0 : -1.0;
                float a = atan(r.y, r.x) + sg * (1.5708 - 0.35 * sin(rl / (Sw * 0.25))) + time * amzp_swirlMove * 0.5 * sg;
                float w = exp(-rl * rl / (Sw * Sw * 0.4)) + 0.002;
                acc += w * float2(cos(2.0 * a), sin(2.0 * a));
            }
        }
        return acc / max(length(acc), 1e-4);
    }
    float flowAngle(float2 c, float s, float swl) {
        float rg = s * 0.5 * max(amzp_flowSmooth, 0.1);
        float gx = luma(src(c + float2(rg, 0.0)).rgb) - luma(src(c - float2(rg, 0.0)).rgb);
        float gy = luma(src(c + float2(0.0, rg)).rgb) - luma(src(c - float2(0.0, rg)).rgb);
        float E = length(float2(gx, gy));
        float at = atan(gy, gx) + 1.5708;
        float we = clamp(amzp_edgeFollow, 0.0, 1.0) * smoothstep(0.02, 0.14, E);
        float ba = radians(amzp_baseAngle);
        float2 vb = float2(cos(2.0 * ba), sin(2.0 * ba));
        float2 vs = mix(vb, swirlVec(c), clamp(swl, 0.0, 1.0));
        float2 v = we * float2(cos(2.0 * at), sin(2.0 * at)) + (1.0 - we) * vs;
        return 0.5 * atan(v.y, v.x);
    }
    void nmMain() {
        float2 W = layer;
        float2 uvL = amzLayerNorm();
        float4 orig = layerAt(uvL);
        float a0 = orig.a;
        if (a0 < 0.001 && !(amzp_overdrawOn>0.5)) { amzOutput = float4(0.0); return; }
        gpx = pxs(); gW = W;
        gfr = (amzp_boil>0.5) ? floor(time * max(amzp_boilFps, 1.0)) : 0.0;
        float2 p = uvL * W / gpx;
        float sc = max(amzp_advScale, 0.01);
        float P = clamp(amzp_paintProg + ((amzp_autop>0.5) ? time * (amzp_autoSpeed * 0.25) : 0.0), 0.0, 1.0);
        float lenM = 1.0, widM = 1.0, swlA = 0.0, impM = 1.0, briM = 1.0, outM = 0.0, soft = 0.2, opa = 1.0, satA = 0.0, canM = 1.0, pool = 0.0;
        if (int(amzp_style) == 0) { lenM = 1.5; widM = 0.9; swlA = 0.35; impM = 1.2; briM = 1.0; outM = 1.0; satA = 0.08; }
        else if (int(amzp_style) == 1) { lenM = 1.0; widM = 1.0; impM = 0.7; briM = 0.6; outM = 0.4; soft = 0.3; }
        else if (int(amzp_style) == 2) { lenM = 0.7; widM = 0.8; impM = 0.2; briM = 1.8; soft = 0.5; canM = 1.6; satA = -0.1; }
        else if (int(amzp_style) == 3) { lenM = 1.3; widM = 1.5; impM = 0.0; briM = 0.2; soft = 0.9; opa = 0.7; pool = 1.0; canM = 1.8; satA = -0.05; }
        else { lenM = 0.2; widM = 0.8; impM = 0.4; briM = 0.0; soft = 0.2; satA = 0.15; }
        float swl = amzp_swirl + swlA;
        float3 blur0 = blurAt(p, amzp_brushSize * 1.2 * sc);
        float3 bef = int(amzp_before) == 1 ? amzp_canvasColor.rgb : (int(amzp_before) == 2 ? blurAt(p, amzp_brushSize * 3.0 * sc) : orig.rgb / max(a0, 1e-4));
        float3 col = mix(bef, blur0, smoothstep(0.88, 1.0, P));
        if (int(amzp_style) == 4) col = mix(col, amzp_canvasColor.rgb, smoothstep(0.88, 1.0, P) * 0.8);
        int nl = int(clamp(floor(amzp_layers + 0.5), 1.0, 4.0));
        float3 oc = float3(0.0); float ocA = 0.0;
        float2 ld = float2(cos(radians(amzp_lightAngle)), -sin(radians(amzp_lightAngle)));
        for (int k = 0; k < 4; k++) {
            if (k >= nl) break;
            float fk = float(k);
            float s = amzp_brushSize * sc * pow(1.9, float(nl - 1 - k));
            float cell = s * 1.25;
            float2 off = float2(fk * 7.3, fk * 3.1);
            float2 gi = floor(p / cell + off);
            float bestPr = 0.0; float bestMask = 0.0; float3 bestCol = float3(0.0);
            for (int j = -1; j <= 1; j++) {
                for (int i = -1; i <= 1; i++) {
                    float2 id = gi + float2(float(i), float(j));
                    float2 c = (id + float2(hs(id, 11.0 + fk), hs(id, 12.0 + fk)) - off) * cell;
                    float o = hs(id, 13.0 + fk);
                    float ts = clamp((P * float(nl) - fk - 0.65 * o) / 0.35, 0.0, 1.0);
                    if (ts <= 0.0) continue;
                    float hl = min(s * amzp_strokeLen * lenM * 0.7, cell * 1.05) * (0.75 + 0.5 * hs(id, 14.0 + fk));
                    float hw = max(s * 0.5 * amzp_strokeWid * widM * (0.8 + 0.4 * hs(id, 15.0 + fk)), 0.5);
                    if (int(amzp_style) == 4) hl = hw;
                    float2 d = p - c;
                    if (dot(d, d) > (hl + hw) * (hl + hw)) continue;
                    float4 sc0 = src(c);
                    if (sc0.a < 0.02) continue;
                    float ang = flowAngle(c, s, swl) + (hs(id, 16.0 + fk) - 0.5) * 3.1416 * amzp_jitter * 0.6;
                    float2 ax = float2(cos(ang), sin(ang));
                    float2 pv = float2(-ax.y, ax.x);
                    float ua = dot(d, ax) / hl;
                    float t = dot(d, pv) / hw;
                    float e = pow(abs(ua), 3.0) + t * t;
                    float mask = 1.0 - smoothstep(1.0 - soft, 1.0, e);
                    if (int(amzp_style) == 4) mask = 1.0 - smoothstep(1.0 - soft, 1.0, ua * ua + t * t);
                    float head = -1.0 + 2.2 * ts;
                    mask *= 1.0 - smoothstep(head - 0.15, head, ua);
                    float bri = clamp(amzp_bristle * briM, 0.0, 1.0);
                    float bn = vn(float2(t * 3.5 + hs(id, 17.0 + fk) * 40.0, ua * 0.7 + fk), 5.0);
                    mask *= 1.0 - 0.7 * bri * smoothstep(0.55, 1.0, abs(ua) + (bn - 0.5) * 0.8);
                    mask *= opa;
                    if (mask < 0.02) continue;
                    float pr = o * mask + mask * 0.02;
                    if (pr <= bestPr) continue;
                    float3 c3 = sc0.rgb;
                    float l = luma(c3);
                    c3 = mix(float3(l), c3, max(amzp_saturation + satA, 0.0));
                    c3 = (c3 - 0.5) * amzp_contrast + 0.5;
                    c3 *= 1.0 + (float3(hs(id, 18.0 + fk), hs(id, 19.0 + fk), hs(id, 20.0 + fk)) - 0.5) * amzp_colorVar * float3(0.7, 0.6, 0.8);
                    if (amzp_levels > 0.5) { float n = max(amzp_levels, 2.0); c3 = floor(c3 * n + 0.5) / n; }
                    c3 *= 1.0 + bri * (bn - 0.5) * 0.45;
                    float2 nrm = pv * t * 0.8 + ax * pow(abs(ua), 3.0) * sign(ua) * 0.6 + pv * (bn - 0.5) * bri * 0.9;
                    float sh = dot(nrm, ld);
                    float imp = amzp_impasto * impM;
                    c3 *= 1.0 + imp * sh * 0.5;
                    c3 += float3(pow(max(sh, 0.0), 5.0)) * imp * 0.22;
                    float er = smoothstep(0.7, 1.0, sqrt(e));
                    c3 = mix(c3, amzp_outlineColor.rgb, clamp(amzp_outline * outM, 0.0, 1.0) * er);
                    if (pool > 0.0) c3 *= 1.0 - 0.25 * er;
                    bestPr = pr; bestMask = mask; bestCol = c3;
                }
            }
            if (bestPr > 0.0) { col = mix(col, bestCol, bestMask); oc = bestCol * bestMask + oc * (1.0 - bestMask); ocA = bestMask + ocA * (1.0 - bestMask); }
        }
        float cs = 2.4 * max(amzp_canvasScale, 0.05);
        float weave = 0.5 + 0.25 * sin(p.x / cs * 3.1416) * sin(p.y / cs * 3.1416) + 0.5 * (vn(p / (cs * 0.8), 9.0) - 0.5);
        col *= 1.0 + amzp_canvasAmt * canM * 0.35 * (weave - 0.5);
        col = clamp(col, 0.0, 1.0);
        if (a0 < 0.001) {
            float k = clamp(amzp_amount, 0.0, 1.0);
            amzOutput = float4(clamp(oc, 0.0, 1.0), ocA) * k;
            return;
        }
        float3 res = mix(orig.rgb / a0, col, clamp(amzp_amount, 0.0, 1.0));
        amzOutput = float4(res * a0, a0);
        if ((amzp_overdrawOn>0.5)) amzOutput = max(amzOutput, float4(clamp(oc, 0.0, 1.0), ocA) * clamp(amzp_amount, 0.0, 1.0));
    }
    void amzRender() {
        if ((amzp_safeRender>0.5)) { amzOutput = amzTexture(0, amzScreenNorm()); return; }
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
